import { DatePipe } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, ElementRef, OnInit, Renderer2 } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { cloneDeep } from '@apollo/client/utilities';
import { PDFGenerator } from '@ionic-native/pdf-generator/ngx';
import { AlertController } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { CWSNService } from 'src/app/services/cwsn.service';
import { IonicStorageService } from 'src/app/services/ionic-storage/ionic-storage.service';
import { NetworkService } from 'src/app/services/network-service';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { environment } from 'src/environments/environment';

@Component({
  selector: 'app-ca-intervention',
  templateUrl: './ca-intervention.page.html',
  styleUrls: ['./ca-intervention.page.scss'],
})
export class CaInterventionPage implements OnInit {

  InterventionList: any = [];
  allStudentData: any;
  routeData: any;
  title: any;
  mode: any;
  // menuValue: any;
  indexVal: any;
  ratting: any[];
  stuRate: any[];

  stars: any[];
  studIndex: any;
  value: any;
  ratingText: any;
  messages: any;
  addCount: number;
  studentDetails: any;
  language: string;
  studentData: any;
  studName: any;
  schlId: any;
  studId: any;
  user_id: any;
  goalList: any[];
  assGoalList: any[];
  currNetWrkSts: any;
  serverData: any;
  domainArray: any[];
  goalArray: any;
  assessmentQstnList: any[];
  assStudDetails: any[];
  qstnArray: any = [];
  assessmentList: any = [];
  questionList: any = [];
  assSave: boolean;
  pipe = new DatePipe("en-US");
  optionList: [];
  skillIndexVal: any;
  timeStamp = new Date();

  supportList = [
    { label: 'Adaptation in the School and Class Room Required', value: 1 },
    { label: 'Home-Based', value: 2 },
    { label: 'School + Center', value: 3 },
    { label: 'Home + Center', value: 4 },
    { label: 'No Therapeutic Intervention', value: 5 },
  ];
  stuFundData: any = [];
  content: string;
  optnArray: any = [];
  interventionArray: any[];
  user_name: any;
  interventionReport:any = [];
  userType1:any = '';
  class_id:any = '';


  constructor(
    private router: Router,
    private http: HttpClient,
    private eRef: ElementRef,
    private renderer: Renderer2,
    private route: ActivatedRoute,
    private cwsnService: CWSNService,
    private pdfGenerator: PDFGenerator,
    private alertService: AlertService,
    private networkService: NetworkService,
    private sqliteDB: SqlitedatabaseService,
    private alertController: AlertController,
    private ionicstorage: IonicStorageService,
    private userSessionService: UserSessionService
  ) { }

  ngOnInit() {
    this.stars = [0, 1, 2, 3, 4];
    this.messages = [];
    // this.initialValidators();
    // this.getInterventionList();
  }

  ionViewDidEnter() {
    this.ratting = [
      { label: '0', value: '0', rate: '' },
      { label: '1', value: '1', rate: '' },
      { label: '2', value: '2', rate: '' },
      { label: '3', value: '3', rate: '' },
      { label: '4', value: '4', rate: '' }
    ];
    this.currNetWrkSts = this.networkService.getCurrentNetworkStatus();
    this.user_id = this.userSessionService.emis_username();
    this.user_name = this.userSessionService.teacher_name();    
    this.userType1 = this.userSessionService.emis_usertype1();    

    this.route.queryParams.subscribe(data => {
      this.allStudentData = JSON.parse(data.item);
    })

    this.routeData = this.route.snapshot;
    this.title = this.routeData.queryParams.title;
    // this.menuValue = this.routeData.queryParams.menuValue
    this.mode = this.routeData.queryParams.mode;
    this.ionicstorage.getData('studentData').then(
      (studData) => {
        this.studentData = studData
        this.studName = studData.Name;
        this.schlId = studData.SchlId;
        this.studId = studData.studId;
        this.class_id = studData.Class?String(studData.Class):'';

        this.stuFundData = [];
        this.ionicstorage.getData('stuFunData').then(
          (stuFunData) => {
            this.stuFundData = stuFunData
            this.checklocalDB();
            // this.checkAssementLocal();
          })
      })

  }

  getInterventionList() {
    let intervention_json = environment.cwsn_intervensions_phase2;
    this.http.get<any>(intervention_json).subscribe((data) => {
      this.InterventionList = data.cwsn_inter_phase2;
      if (data.cwsn_inter_phase2.length > 0) {
        this.insertInterventionData(data.cwsn_inter_phase2);
      } else {
        this.alertService.warning('No Interventions Found');
      }
    })
  }

  headerAccord(i) {
    if (this.indexVal == i) {
      this.indexVal = ''
    } else {
      this.indexVal = i
    }
  }

  skillheaderAccord(i, j) {
    if (this.skillIndexVal == [i][j]) {
      this.skillIndexVal = ''
    } else {
      this.skillIndexVal = [i][j]
    }
  }

  checkAssementLocal() {
    let query = 'SELECT * FROM intervention_qstns';
    this.sqliteDB.executeQuery(query).then(res => {
      if (res.rows.length > 0) {
        let temp = [];
        for (var i = 0; i < res.rows.length; i++) {
          temp.push(res.rows.item(i));
        }
        this.assessmentQstnList = temp;
        this.assessmentQstnList = temp.filter(obj=>{
          let clsSplit = obj.age_category ? obj.age_category.split(",") : [];
          return clsSplit.includes(this.class_id);
        });
        this.interventionArray = [];
        this.assStudDetails.forEach(ele => {
          let domainIndex = this.assessmentQstnList.find((key) => key.intervension_idx_id == ele.intervension_idx_id);
          if (domainIndex) {
            domainIndex.domain_id = cloneDeep(ele.domain_id);
            domainIndex.domain_name = cloneDeep(ele.domain_name);
            this.interventionArray.push(cloneDeep(domainIndex));
          }
        })
        this.makingFormArray();
      } else {
        this.getInterventionList();
      };
    });
  };

  async checklocalDB() {
    this.interventionArray = [];
    this.assessmentList = [];
    let query;
    // query = 'SELECT * FROM stud_int_assessment' +
    // ' WHERE user_id = "' + this.user_id + '"' +
    // ' AND stud_id = "' + this.studId + '"' +
    // ' AND goal_val = 1';
    query = 'SELECT * FROM stud_int_assessment' +
      ' WHERE user_id = "' + this.user_id + '"' +
      ' AND stud_id = "' + this.studId + '"';

    await this.sqliteDB.executeQuery(query).then((res) => {
      this.assStudDetails = [];
      if (res.rows.length > 0) {
        let asstemp = [];
        for (var i = 0; i < res.rows.length; i++) {
          asstemp.push(res.rows.item(i));
        }
        this.assStudDetails = asstemp.filter(obj=>{
          return obj.goal_val == 1;
        });
        // this.makingFormArray();
        this.checkAssementLocal();
      } else {
        this.assStudDetails = [];
        // this.makingFormArray();
        this.getDatafromServer();
      }
    });
  }

  async getDatafromServer() {
    if (this.currNetWrkSts == 0) {
      this.cwsnService.getStudInterventionDetails(this.user_id, this.studId).subscribe(res => {
        if (res.dataStatus == true) {
          if (res.result.length > 0) {
            this.serverData = res.result;
            this.insertStudInterDataLocal(res.result, 3)
          } else {
            this.serverData = [];
            this.makingFormArray();
          }
        } else {
          this.serverData = [];
          this.makingFormArray();
        }
      })
    } else {
      this.makingFormArray();
    }
  }

  makingFormArray() {
    if(this.interventionArray.length > 0) {
      this.domainArray = [...new Map(this.interventionArray.map(item =>
        [item['domain_id'], item])).values()];
      // setTimeout(() => {
      if (this.domainArray.length > 0) {
      this.domainFormDetails(this.domainArray)
      } else {
      }
    } else {
      this.interventionArray = [];
    }
  }

  groupByQstn(qstnList) {
    var helper = {};
    // this.qstnArray = [];
    this.qstnArray.push(qstnList.reduce(function (r, o) {
      var key = o.domain_id + '-' + o.skills + '-' + o.sub_skills;
      if (!helper[key]) {
        helper[key] = Object.assign({}, o); // create a copy of o
        r.push(helper[key]);
      } else {
        helper[key].used += o.used;
        helper[key].instances += o.instances;
      }
      return r;
    }, []));
  }

  //set form values for yearly leaves
  domainFormDetails(data) {
    console.log('subDomain data', data, 'assessmentQstnList', this.assessmentQstnList)
    this.assessmentList = [];
    this.qstnArray = [];
    this.interventionReport = [];

    for (let i = 0; i < data.length; i++) {

      // let myPromise = new Promise(function(myResolve, myReject) {
      let qstnIndex = this.interventionArray.filter((key) => key.domain_id == data[i].domain_id);

      // myPromise.then(
      //   function(value) {
      // var qstnIndex : any = value
      // set form values for yearly leaves
      setTimeout(() => {
        this.assessmentList.push({
          domain_id: data[i].domain_id,
          domain: data[i].domain_name,
          subdomain_id: data[i].subdomain_id,
          sub_domain: data[i].sub_domain,
        });
        // debugger

        this.groupByQstn(qstnIndex)
        this.optnArray = [];
        this.assessmentList[i].questionList = [];
        for (let j = 0; j < this.qstnArray[i].length; j++) {
          let question = this.qstnArray[i][j];
          let optnIndex = qstnIndex.filter((key) => key.domain_id == question.domain_id && (key.skills == question.skills && key.sub_skills == question.sub_skills));
          // setTimeout(() => {
          this.assessmentList[i].questionList.push({
            intervention_type_id: question.intervention_type_id,
            intervention_type: question.intervention_type,
            intervension: question.intervension,
            intervension_tamil: question.intervension_tamil,
            skills: question.skills,
            sub_skills: question.sub_skills,
          });

          this.assessmentList[i].questionList[j].optionList = [];
          for (let k = 0; k < optnIndex.length; k++) {
            let option = optnIndex[k];
            let newObj = {
              index_id: option.index_id,
              intervension_idx_id: option.intervension_idx_id,
              intervention_type_id: option.intervention_type_id,
              intervention_type: option.intervention_type,
              intervension: question.intervension,
              intervension_tamil: question.intervension_tamil,
              goal: option.goal,
              goal_tamil: option.goal_tamil,
              rate_val: option.rate_val,
              goal_val: option.goal_val,
              inter_status: option.inter_status,
              domain_id: data[i].domain_id,
              domain: data[i].domain_name,
              skills: question.skills,
              sub_skills: question.sub_skills
              };
            this.assessmentList[i].questionList[j].optionList.push(cloneDeep(newObj));
            this.interventionReport.push(cloneDeep(newObj))
          }
        }
      }
      );
    }
  }

  insertStudInterDataLocal(submitArray, status) {
    let delQuery = 'DELETE FROM stud_int_assessment' +
      ' WHERE user_id = "' + this.user_id + '"' +
      ' AND stud_id = "' + this.studId + '"';
    this.sqliteDB.executeQuery(delQuery).then(res => {
      let sqlArray = [];
      submitArray.forEach(element => {
        sqlArray.push(['INSERT INTO stud_int_assessment (Id,index_id,user_id,schl_id,stud_id,domain_id,domain_name,subdomain_id,intervension_idx_id,intervention_type_id,rate_val,goal_val,support,date,inter_status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', [null, element.id, element.user_id, element.school_id, element.student_id, element.domain_id, element.domain_name, element.subdomain_id, element.intervension_idx_id, element.evaluation_type, parseInt(element.rating), element.goal, element.support_in, this.pipe.transform(new Date(), "yyyy-MM-dd"), 2]]);
      });
      this.sqliteDB.bulkInsert(sqlArray).then((insertres) => {
        // this.insertStudDomainlocal();
        if (status == 3) {
          this.checklocalDB();
        }
        // this.router.navigate(['/tabs/ca-student-list'], { queryParams: { item: JSON.stringify(item), 'zonleId': this.ZonalId, title: this.title, mode: this.mode } });
      });
      // }
    });
  }

  insertInterventionData(list) {
    let sqlArray = [];
    list.forEach(element => {
      // element.screen = 0;
      sqlArray.push(['INSERT INTO intervention_qstns VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', [null, this.user_id, element.user, this.studId, this.allStudentData.Name, '', '', element.subdomain_idx_id, element.sub_domain, element.id, element.intervention_type_id, element.intervention_type, element.intervension, element.intervension_tamil, element.skills, element.sub_skills, element.goal, element.goal_tamil, element.inter_status, element.age_category]]);
    });
    this.sqliteDB.bulkInsert(sqlArray).then((insertres) => {
      this.checkAssementLocal();
    });
  };

  navigateBack() {
    this.router.navigate(['/tabs/ca-student-list'], { queryParams: { item: JSON.stringify(this.allStudentData), title: this.title, mode: this.mode } });
    // this.router.navigate(["/tabs/ca-domain-list"], { queryParams: { title: this.title, mode: this.mode } });
  }

  downloadAsPDF(id) {
    // this.cwsnService.generatePdf(id); 
    this.content = document.getElementById(id).innerHTML;
    let options = {
      documentSize: 'A4',
      type: 'share',
      // landscape: 'portrait',
      fileName: 'cwsn_intervetsion_' + this.studName + '.pdf'
    };
    this.pdfGenerator.fromData(this.content, options)
      .then((base64) => {
        console.log('OK', base64);
      }).catch((error) => {
        console.log('error', error);
      });

      let data = {
          "records":{
              "student_id" : this.studId
          }
      }
 
      console.log('attendance data',data);
 
      this.cwsnService.pdfDownloadLog(data).subscribe(res => {
        if (res.dataStatus) {
 
        }
      })
  }

  async presentAlert() {
    const alert = await this.alertController.create({
      cssClass: 'cwsn-eval-custom-class',
      message: `
      <div><img src="../../../../assets/icons/cwsn/check_mark.png" alt="g-maps"> </div>
      <div class="alert-message"><p>Congratulations</p> </div>
      <div class="alert-subhead"><p>` + this.user_name + `</p> </div>
        <div class="alert-content">
          <div class="title">Evaluated Successfully.</div>
          <div class="stars">
            <span>★</span>
            <span>★</span>
            <span>★</span>
            <span>★</span>
            <span>★</span>
          </div>
        </div>`,

      buttons: [{
        text: 'Close',
        cssClass: 'alert-button-cancel',
        handler: data => {
          this.router.navigate(['/tabs/ca-student-list'], { queryParams: { item: JSON.stringify(this.allStudentData), title: this.title, mode: this.mode } });
        }
      },]
    });

    await alert.present();
  }

}
